Path('tests/e2e/stability-bifurcation.spec.ts').write_text(r'''import { expect, test, type Page } from '@playwright/test';

async function storedProject(page:Page){return page.evaluate(()=>{const raw=localStorage.getItem('astrastruct.project');return raw?JSON.parse(raw):null})}
async function openCommand(page:Page,label:string){const width=page.viewportSize()?.width||1280;if(width<=1100){const more=page.locator('button[aria-label="Mais comandos"]:visible').first();await expect(more).toBeVisible();await more.click();const command=page.locator(`.command-sheet button[aria-label="${label}"]:visible`).first();await expect(command).toBeVisible();await command.click();return}const direct=page.locator(`button[aria-label="${label}"]:visible`).first();if(await direct.isVisible().catch(()=>false)){await direct.click();return}const library=page.locator('.library-tools button').filter({hasText:label}).first();await expect(library).toBeVisible();await library.click()}
async function installEulerColumn(page:Page){await page.goto('./');await page.evaluate(()=>{const raw=localStorage.getItem('astrastruct.project');if(!raw)throw new Error('Projeto inicial ausente');const p=JSON.parse(raw),L=4,n=8,P=10000,E=200e6,I=8e-5,A=.01;p.name='E2E — stability v0.18';p.materials=[{id:'S',name:'Steel elastic',type:'steel',E,nu:.3,density:0,alpha:12e-6,fy:355}];p.sections=[{id:'SEC',name:'Column',family:'rect',b:.1,h:.8,A,I}];p.nodes=Array.from({length:n+1},(_,i)=>({id:`N${i}`,x:0,y:L*i/n}));p.elements=[];for(let i=0;i<n;i++)p.elements.push({id:`E${i+1}`,type:'frame2d',n1:`N${i}`,n2:`N${i+1}`,materialId:'S',sectionId:'SEC',A,I,releases:{rz1:false,rz2:false},rotationalSprings:{rz1:null,rz2:null}});p.supports=[{nodeId:'N0',ux:true,uy:true,rz:false},{nodeId:`N${n}`,ux:true,uy:false,rz:false}];p.loads=[{id:'P',caseId:'LC1',nodeId:`N${n}`,fx:0,fy:-P,mz:0}];p.elementLoads=[];p.nodeSprings=[];p.settlements=[];p.settings={...(p.settings||{}),analysisType:'linear',activeLoadCaseId:'LC1',analysisScenarioId:'LC1',nonlinearSteps:30,nonlinearMaxIterations:70,nonlinearTolerance:1e-9,nonlinearLineSearch:true,imperfection:{...(p.settings?.imperfection||{}),enabled:false}};localStorage.setItem('astrastruct.project',JSON.stringify(p))});await page.reload()}

test('v0.18 detects Euler bifurcation and seeds the critical branch',async({page})=>{await installEulerColumn(page);await expect(page.getByTestId('astra-app')).toBeVisible();await openCommand(page,'Tipo de análise');await page.getByTestId('analysis-corotational').click();await page.getByTestId('nonlinear-control-mode').selectOption('arc-length');await page.getByTestId('arc-length-monitor-node').selectOption('N4');await page.getByTestId('arc-length-monitor-dof').selectOption('ux');await page.getByTestId('arc-length-initial-load-increment').fill('0.06');await page.getByTestId('nonlinear-steps').fill('30');await expect(page.getByTestId('stability-tracking')).toBeChecked();await page.getByTestId('stability-eigen-tolerance').fill('0.08');await page.getByTestId('stability-asymmetry-tolerance').fill('0.0000001');await page.getByTestId('branch-switch-enabled').check();await page.getByTestId('branch-switch-amplitude').fill('0.12');await page.getByTestId('analysis-apply').click();await expect.poll(async()=>{const p=await storedProject(page);return [p?.settings?.analysisType,p?.settings?.nonlinearControlMode,p?.settings?.stabilityTracking,p?.settings?.branchSwitchEnabled,Number(p?.settings?.branchSwitchAmplitude)]}).toEqual(['corotational','arc-length',true,true,.12]);await page.getByTestId('analyze-button').click();const results=page.locator('.results-content');await expect(results).toContainText('frame2d-corotational-arc-length-experimental');await expect(results).toContainText('0.18.0-exp');await expect(page.locator('[role="alert"]')).toHaveCount(0);await openCommand(page,'Diagramas/envelopes');const post=page.getByTestId('panel-nonlinear-postprocess');await expect(post).toBeVisible();await expect(page.getByTestId('stability-summary')).toContainText('bifurcação');await expect(page.getByTestId('stability-bifurcation-marker')).toHaveCount(1);await expect(page.getByTestId('branch-switch-marker')).toHaveCount(1);await post.locator('button[aria-label="Fechar"]').click();await openCommand(page,'Relatório técnico');const report=page.getByTestId('panel-nonlinear-report');await expect(report).toBeVisible();await expect(page.getByTestId('stability-report')).toContainText('bifurcation-candidate');await expect(page.getByTestId('stability-report')).toContainText('Troca de ramo experimental');await expect(page.locator('[role="alert"]')).toHaveCount(0)});
''')

